WHERE g.tenant_id = #{tenantId}
  AND g.query_hash = #{queryHash}
  AND g.data_version = #{dataVersion}


          AND abc.current_abc = #{currentAbc}


          AND abc.compare_abc = #{compareAbc}




          AND g.current_gross_role = #{currentGrossRole}


          AND g.compare_gross_role = #{compareGrossRole}




          AND g.current_gmroi_role = #{currentGmroiRole}


          AND g.compare_gmroi_role = #{compareGmroiRole}



      AND g.product_status_no IN

          #{status}



      AND g.first_sale_date <= #{firstSaleDate}


      AND pb.price_band_label IN

          #{priceBand}



      AND g.brand_name IN

          #{brand}



      AND g.spec IN

          #{spec}



      AND pti.tag_no IN

          #{tag}
